<script>
  const button = document.querySelector('[data-theme-switcher]')
  if (button) {
    button.addEventListener('click', () => {
      const toggle_nav = document.querySelector<HTMLInputElement>('#toggle_nav')
      if (toggle_nav) {
        toggle_nav.checked = false
      }
    })
  }
</script>

<style>
  @reference "../../styles/global.css";

  #toggle_nav:checked ~ div #hamburger #line {
    @apply translate-y-1.5 rotate-45;
  }

  #toggle_nav:checked ~ div #hamburger #line2 {
    @apply -translate-y-1 -rotate-45;
  }

  #toggle_nav:checked ~ div #top_links {
    @apply hidden;
  }

  #toggle_nav:checked ~ div #search {
    @apply hidden;
  }
</style>

<script>
  const externalLinks = document.querySelectorAll('#external')
  const parent = externalLinks.item(0)?.parentElement

  function checkVisibility() {
    const parentRect = parent?.getBoundingClientRect()
    if (parentRect) {
      for (const link of externalLinks) {
        const rect = link.getBoundingClientRect()

        const isVisible =
          rect.top >= parentRect.top &&
          rect.left >= parentRect.left &&
          rect.bottom <= parentRect.bottom &&
          rect.right <= parentRect.right

        if (!isVisible) {
          link.classList.add('invisible')
        } else {
          link.classList.remove('invisible')
        }
      }
    }
  }

  document.addEventListener('DOMContentLoaded', checkVisibility, { once: true })
  if (parent) new ResizeObserver(checkVisibility).observe(parent)
</script>

